import{_ as t,o,c as a,a2 as i}from"./chunks/framework.l66uSLlc.js";const k=JSON.parse('{"title":"Theming Noto","description":"","frontmatter":{},"headers":[],"relativePath":"guide/theming.md","filePath":"guide/theming.md","lastUpdated":1789542331000}'),s={name:"guide/theming.md"};function d(n,e,r,h,c,l){return o(),a("div",null,[...e[0]||(e[0]=[i(`<h1 id="theming-noto" tabindex="-1">Theming Noto <a class="header-anchor" href="#theming-noto" aria-label="Permalink to &quot;Theming Noto&quot;">​</a></h1><p>Noto is themed with one CSS file of your own. You name it once in Settings, under Appearance, and reload it from the same place while you edit it in your usual editor. Nothing is pasted into a text area and nothing is compiled: the file is read as it is and layered over the built-in styles.</p><p>This guide covers what the file can reach, what it cannot, and the handful of rules that make a theme hold up across light and dark, the width modes, and the settings a reader may change under it.</p><h2 id="loading-a-theme" tabindex="-1">Loading a theme <a class="header-anchor" href="#loading-a-theme" aria-label="Permalink to &quot;Loading a theme&quot;">​</a></h2><p>Settings, Appearance, Custom stylesheet. The field takes an absolute path to a <code>.css</code> file, committed on blur or Enter. Reload re-reads the file; a path that cannot be read is reported beside the field rather than failing quietly. The file is limited to a size a stylesheet should never approach, and a relative path is refused because it would resolve against whatever the process happened to consider its working directory.</p><p>The stylesheet is applied through the document&#39;s adopted style sheets, not as a <code>&lt;style&gt;</code> element, because the renderer&#39;s content security policy allows no inline styles. That is also why a theme cannot <code>@import</code> a remote sheet or load a web font: the policy allows fonts only from the application itself. Use fonts installed on the machine.</p><h2 id="the-palette-is-yours-to-override" tabindex="-1">The palette is yours to override <a class="header-anchor" href="#the-palette-is-yours-to-override" aria-label="Permalink to &quot;The palette is yours to override&quot;">​</a></h2><p>Every colour in the app comes from a small set of custom properties on the root element. They are declared inside a cascade layer named <code>noto-tokens</code>, and a theme file is unlayered, so any value you set on <code>:root</code> wins over the built-in one with no selector tricks and no <code>!important</code>. The two themes are distinguished by <code>data-theme=&quot;light&quot;</code> and <code>data-theme=&quot;dark&quot;</code> on the root.</p><div class="language-css vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">css</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">:root</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">--accent</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">#2f6f9f</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; }</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">:root</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">data-theme</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;dark&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">] { </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">--accent</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">#7fb3d5</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; }</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Property</th><th>What it colours</th></tr></thead><tbody><tr><td><code>--paper</code></td><td>The document canvas and the window ground</td></tr><tr><td><code>--panel</code></td><td>The rail, the title bar and Settings</td></tr><tr><td><code>--raised</code></td><td>Hover surfaces, code fences, quiet fills, the find bar</td></tr><tr><td><code>--overlay</code></td><td>A panel floating over the scrim: Settings and quick open</td></tr><tr><td><code>--ink</code></td><td>Body text</td></tr><tr><td><code>--ink-strong</code></td><td>Headings, bold, a table&#39;s first column</td></tr><tr><td><code>--muted</code></td><td>Secondary text, folder names, labels</td></tr><tr><td><code>--hairline</code></td><td>Rules and borders</td></tr><tr><td><code>--line-strong</code></td><td>A table&#39;s outer rules, the rule under a stuck folder row</td></tr><tr><td><code>--accent</code></td><td>The one mark for where you are, links, the caret</td></tr><tr><td><code>--code-ink</code>, <code>--code-fill</code></td><td>Inline code&#39;s text and fill</td></tr><tr><td><code>--code-text</code></td><td>The text of a fenced block, before any highlighting</td></tr><tr><td><code>--code-guide</code></td><td>The rules at each tab stop of a code line&#39;s indentation</td></tr><tr><td><code>--code-keyword</code>, <code>--code-string</code>, <code>--code-number</code>, <code>--code-symbol</code>, <code>--code-muted</code></td><td>The five colours a fenced block is drawn in: reserved words, text, numbers, names the code defines, and comments</td></tr><tr><td><code>--surface-active</code></td><td>The fill behind the current file&#39;s row</td></tr><tr><td><code>--quote-ink</code>, <code>--quote-line</code></td><td>A blockquote&#39;s text and its rule</td></tr><tr><td><code>--task-done</code></td><td>A finished task item</td></tr><tr><td><code>--alert-note</code>, <code>--alert-tip</code>, <code>--alert-important</code>, <code>--alert-warning</code>, <code>--alert-caution</code></td><td>The rule, tint and title of each kind of <code>[!NOTE]</code> callout</td></tr><tr><td><code>--mark-fill</code></td><td>The fill behind <code>==highlighted==</code> text and <code>&lt;mark&gt;</code></td></tr><tr><td><code>--success</code>, <code>--warning</code>, <code>--danger</code></td><td>Status only</td></tr><tr><td><code>--focus</code></td><td>Keyboard focus rings</td></tr><tr><td><code>--scrim</code></td><td>The wash behind Settings and quick open</td></tr><tr><td><code>--tree-line</code></td><td>The connector lines in the file tree and outline</td></tr></tbody></table><p>Set light values on <code>:root</code> and dark values on <code>:root[data-theme=&#39;dark&#39;]</code>. A theme that sets only one of the two leaves the other as shipped, which is usually what you want while you work.</p><h2 id="typography-and-the-page" tabindex="-1">Typography and the page <a class="header-anchor" href="#typography-and-the-page" aria-label="Permalink to &quot;Typography and the page&quot;">​</a></h2><p>The document&#39;s size and leading come from settings and arrive as properties on the root: <code>--doc-font-size</code> and <code>--doc-line-height</code>. A theme should not set these; the reader owns them. Everything in the document that has a size is in <code>em</code>, so it follows the setting: headings are 1.84, 1.48, 1.24 and 1.12 of the body, code is 0.9, tables 0.92. Override the ratios if you want a different scale, and it will still follow the reader&#39;s size.</p><div class="language-css vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">css</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">.ProseMirror</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;"> h1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">font-size</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">em</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; }</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">.ProseMirror</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> :not</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">pre</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;"> code</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">font-size</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0.88</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">em</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; }</span></span></code></pre></div><p>The width of the writing column is a mode, not a number: <code>default</code>, <code>wide</code> or <code>full</code>, carried on the root as <code>data-width-mode</code>. Each mode is the smaller of the canvas less its gutters and a cap, so the column can never be wider than the canvas and the document never scrolls sideways. The cap for each mode is <code>--measure-cap</code>, and the gutter is <code>--canvas-gutter</code>; a theme may change either, and should keep the <code>min()</code> shape if it replaces <code>--measure</code> outright.</p><div class="language-css vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">css</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">:root</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">--measure-cap</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">760</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">px</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; }</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">:root</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">data-width-mode</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;wide&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">] { </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">--measure-cap</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">clamp</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">900</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">px</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">72</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">%</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1100</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">px</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">); }</span></span></code></pre></div><p>The prose face, the interface face and the monospace face are set in the stylesheet rather than as properties. The prose stack is the author&#39;s Typora stack face for face, so a machine missing the first one falls back the way Typora would. To change them, set <code>font-family</code> on <code>.ProseMirror</code> for the document and on <code>body</code> for the chrome.</p><h2 id="what-the-document-is-made-of" tabindex="-1">What the document is made of <a class="header-anchor" href="#what-the-document-is-made-of" aria-label="Permalink to &quot;What the document is made of&quot;">​</a></h2><p>The editor is ProseMirror, so the document is ordinary HTML under <code>.ProseMirror</code> with a few classes of Noto&#39;s own. The ones a theme is likely to want:</p><ul><li>Block rhythm is <code>margin</code> on <code>.ProseMirror &gt; *</code>. The block holding the caret carries <code>.noto-active-block</code>; inline syntax revealed around the caret is <code>.noto-syntax</code>.</li><li>A code fence is <code>pre.noto-fence</code> with <code>.noto-fence-gutter</code> (the line numbers), <code>code.noto-fence-code</code>, and <code>.noto-fence-tools</code> holding <code>.noto-fence-lang</code> and <code>.noto-fence-copy</code>. The gutter&#39;s width is <code>--fence-digits</code> characters, set per block. Syntax tokens are Prism&#39;s <code>.token</code> classes, coloured from the palette.</li><li>A mermaid fence carries <code>data-lang=&quot;mermaid&quot;</code> and holds a <code>.noto-diagram</code> with the drawing in <code>.noto-diagram-frame</code> and, when it failed, a <code>.noto-diagram-status</code>; its <code>data-state</code> is <code>rendering</code>, <code>rendered</code> or <code>failed</code>. The drawing takes its colours from the palette tokens above, read each time it is drawn, so a theme file reaches it without styling the frame.</li><li>A picture is <code>img.noto-image</code> inside <code>.noto-image-frame</code>; one that could not be shown is <code>.noto-image-placeholder</code> with a <code>data-reason</code>.</li><li>A table is wrapped in <code>.noto-table-frame</code>, which also holds the rails it is taken hold of by: <code>.noto-table-rails</code> with <code>.noto-table-rail-rows</code> and <code>.noto-table-rail-columns</code>, each holding one <code>.noto-table-handle</code> per track, and <code>.noto-table-drop</code> for the line showing where a dragged track will land. The handles are invisible until the frame is hovered, carry <code>.noto-table-handle-held</code> while dragged, and the rails carry <code>data-dragging=&quot;row&quot;</code> or <code>&quot;column&quot;</code> for as long as a drag lasts. Tables draw horizontal rules only, from <code>--line-strong</code> and a mix of <code>--muted</code>; a raw HTML block is <code>.noto-html-block</code>, a math block <code>.noto-math-block</code>, frontmatter <code>.noto-frontmatter</code>.</li><li>A GitHub alert is a <code>blockquote.noto-alert</code> with <code>.noto-alert-note</code> or one of the other four kinds, carrying <code>--alert-color</code>; its title chip is <code>.noto-alert-title</code> and the hidden marker <code>.noto-alert-marker</code>. While the caret is inside, the quote carries <code>.noto-alert-editing</code>.</li><li>Typora&#39;s inline marks are decorations over plain text: <code>.noto-mark-highlight</code>, <code>.noto-mark-sup</code>, <code>.noto-mark-sub</code>, with the delimiters in <code>.noto-typora-delim</code>. Bare inline HTML tags are drawn the same way: the tag is <code>.noto-inline-tag</code>, the text between carries <code>.noto-html-kbd</code>, <code>.noto-html-sub</code>, <code>.noto-html-sup</code>, <code>.noto-html-u</code> and so on, and a <code>&lt;br&gt;</code> is <code>.noto-inline-break</code>. A text block whose selection is touching any of these carries <code>.noto-marks-editing</code>, and that is when the syntax shows (editor focus required). Wiki-link brackets use <code>.noto-wiki-bracket</code> and reveal only when the caret&#39;s <code>.noto-source-editing</code> textblock is focused <em>and</em> that match carries <code>.noto-wiki-source-active</code> (span-level).</li><li>Task list items are <code>li.noto-task-item</code> with <code>data-checked</code>; the box is drawn with <code>::before</code> and <code>::after</code>.</li></ul><p>Focus mode is <code>data-focus-mode=&quot;on&quot;</code> on the root, and quietens <code>.ProseMirror &gt; *:not(.noto-active-block)</code>. A theme that wants a different treatment, a blur or a colour rather than an opacity, overrides that one rule.</p><p>Selectors here are stable for the life of a major version. Anything without a <code>noto-</code> prefix, such as ProseMirror&#39;s own classes, is not something a theme should depend on.</p><h2 id="the-chrome" tabindex="-1">The chrome <a class="header-anchor" href="#the-chrome" aria-label="Permalink to &quot;The chrome&quot;">​</a></h2><p>The height of one tree row is <code>--tree-row</code> and the sticky offsets are multiples of it, so a theme that changes the row height gets the stack right for free.</p><p>The rail is <code>.workspace-rail</code>, its tree <code>.tree-root</code>; rows are <code>.tree-row</code> with <code>.tree-directory</code> or <code>.tree-file</code>, the current file <code>.tree-file-active</code>, the folder&#39;s own row <code>.tree-vault-row</code>. Connector lines are drawn with <code>--tree-line</code> and the indent is <code>--tree-indent</code> on <code>.tree-level</code>. Open folder rows are sticky; a row that is actually stuck carries <code>data-stuck</code>.</p><p>The title bar is <code>.titlebar</code>, its icons <code>.icon-button</code>. Settings is <code>.settings-panel</code>. The width of the rail is a setting and arrives as <code>--rail-width</code>.</p><p>Keep in mind the app&#39;s one rule for the chrome: the accent marks where you are and nothing else. A theme that spends the accent on every button will read as louder, not richer.</p><h2 id="checking-a-theme" tabindex="-1">Checking a theme <a class="header-anchor" href="#checking-a-theme" aria-label="Permalink to &quot;Checking a theme&quot;">​</a></h2><p>Look at it three ways before you keep it: in both themes, since the app follows the system by default; at the narrowest window you use, since the width modes converge there; and with the text size setting at both ends, since everything in the document should follow it. A theme that only works at one size is a theme for one afternoon.</p>`,29)])])}const g=t(s,[["render",d]]);export{k as __pageData,g as default};
